42	const PROCESSING_FEE = 5;
43	
44	const BASE_PREMIUM_BY_ITEM_TYPE: Record<string, number> = {
45	  sword: 100,
46	  amulet: 60,
47	  staff: 80,
48	  potion: 40,
49	  rune: 25,
50	};
51	
52	const BLOCK_SIZE = 3;
53	const BLOCK_BASE_PREMIUM = 60;
54	
55	const quote = ({ items }: QuoteStep): StepResult => {
56	  const runeCount = items.filter((item) => item.type === "rune").length;
57	  const totalBasePremium =
58	    runeCount === BLOCK_SIZE
59	      ? BLOCK_BASE_PREMIUM
60	      : items.reduce((total, item) => total + BASE_PREMIUM_BY_ITEM_TYPE[item.type], 0);
61	
62	  return { premium: totalBasePremium + PROCESSING_FEE };
63	};
64	
65	export const runScenario = (scenario: Scenario): ScenarioResult => ({
66	  results: [quote(scenario.steps[0] as QuoteStep)],
67	});
