const formsBlock = (items: Item[]): boolean =>
  items.length === BLOCK_SIZE && items.every((item) => item.type === items[0].type);

const sumBasePremiums = (items: Item[]): number =>
  items.reduce((total, item) => total + BASE_PREMIUM_BY_ITEM_TYPE[item.type], 0);

const quote = ({ items }: QuoteStep): StepResult => {
  const totalBasePremium = formsBlock(items) ? BLOCK_BASE_PREMIUM : sumBasePremiums(items);

  return { premium: totalBasePremium + PROCESSING_FEE };
};
